GET_PRODUCTS_BY_COLLECTION.query:
query GetProductsByCollection($handle: String!, $first: Int!, $after: String, $sortKey: ProductCollectionSortKeys, $reverse: Boolean, $filters: [ProductFilter!]) {
  collection(handle: $handle) {
    id
    title
    description
    seo { title description }
    products(
      first: $first
      after: $after
      sortKey: $sortKey
      reverse: $reverse
      filters: $filters
    ) {
      pageInfo {
        hasNextPage
        hasPreviousPage
        startCursor
        endCursor
      }
      filters {
        id
        label
        type
        values { id label count input }
      }
      edges {
        cursor
        node {
          id
          title
          handle
          tags
          vendor
          productType
          priceRange {
            minVariantPrice { amount currencyCode }
            maxVariantPrice { amount currencyCode }
          }
          compareAtPriceRange {
            minVariantPrice { amount currencyCode }
          }
          featuredImage { url altText width height }
          images(first: 2) {
            edges { node { url altText width height } }
          }
          variants(first: 1) {
            edges {
              node {
                id
                title
                availableForSale
                price { amount currencyCode }
                compareAtPrice { amount currencyCode }
                selectedOptions { name value }
              }
            }
          }
        }
      }
    }
  }
}

GET_PRODUCT_BY_HANDLE.query:
query GetProductByHandle($handle: String!) {
  product(handle: $handle) {
    id
    title
    handle
    description
    descriptionHtml
    vendor
    productType
    tags
    seo { title description }
    priceRange {
      minVariantPrice { amount currencyCode }
      maxVariantPrice { amount currencyCode }
    }
    compareAtPriceRange {
      minVariantPrice { amount currencyCode }
    }
    images(first: 10) {
      edges { node { id url altText width height } }
    }
    options {
      id
      name
      values
    }
    variants(first: 100) {
      edges {
        node {
          id
          title
          availableForSale
          quantityAvailable
          price { amount currencyCode }
          compareAtPrice { amount currencyCode }
          selectedOptions { name value }
          image { url altText }
        }
      }
    }
    metafields(identifiers: [
      { namespace: "custom", key: "country_of_origin" },
      { namespace: "custom", key: "volume" }
    ]) {
      key
      value
    }
  }
}

GET_ALL_COLLECTIONS.query:
query GetAllCollections($first: Int!) {
  collections(first: $first) {
    edges {
      node {
        id
        title
        handle
        image { url altText }
        seo { title description }
      }
    }
  }
}

GET_ALL_VENDORS.query:
query GetAllVendors($first: Int!) {
  products(first: $first) {
    edges {
      node {
        vendor
      }
    }
  }
}

SEARCH_PRODUCTS.query:
query SearchProducts($query: String!, $first: Int!, $after: String) {
  search(query: $query, first: $first, after: $after, types: [PRODUCT]) {
    pageInfo { hasNextPage endCursor }
    edges {
      node {
        ... on Product {
          id
          title
          handle
          vendor
          featuredImage { url altText width height }
          priceRange {
            minVariantPrice { amount currencyCode }
          }
          compareAtPriceRange {
            minVariantPrice { amount currencyCode }
          }
          tags
        }
      }
    }
  }
}

PREDICTIVE_SEARCH.query:
query PredictiveSearch($query: String!) {
  predictiveSearch(query: $query, types: [PRODUCT, COLLECTION]) {
    products {
      id
      title
      handle
      featuredImage { url altText width height }
      priceRange {
        minVariantPrice { amount currencyCode }
      }
    }
    collections {
      id
      title
      handle
    }
  }
}

CREATE_CART.mutation:
mutation CreateCart($input: CartInput!) {
  cartCreate(input: $input) {
    cart {
      id
      checkoutUrl
      totalQuantity
      cost {
        subtotalAmount { amount currencyCode }
        totalAmount { amount currencyCode }
      }
      lines(first: 100) {
        edges {
          node {
            id
            quantity
            cost {
              totalAmount { amount currencyCode }
            }
            merchandise {
              ... on ProductVariant {
                id
                title
                price { amount currencyCode }
                compareAtPrice { amount currencyCode }
                image { url altText }
                product { title handle featuredImage { url } }
              }
            }
          }
        }
      }
    }
    userErrors { field message }
  }
}

ADD_CART_LINES.mutation:
mutation AddCartLines($cartId: ID!, $lines: [CartLineInput!]!) {
  cartLinesAdd(cartId: $cartId, lines: $lines) {
    cart { id totalQuantity cost { subtotalAmount { amount currencyCode } } }
    userErrors { field message }
  }
}

UPDATE_CART_LINES.mutation:
mutation UpdateCartLines($cartId: ID!, $lines: [CartLineUpdateInput!]!) {
  cartLinesUpdate(cartId: $cartId, lines: $lines) {
    cart { id totalQuantity cost { subtotalAmount { amount currencyCode } } }
    userErrors { field message }
  }
}

REMOVE_CART_LINES.mutation:
mutation RemoveCartLines($cartId: ID!, $lineIds: [ID!]!) {
  cartLinesRemove(cartId: $cartId, lineIds: $lineIds) {
    cart { id totalQuantity cost { subtotalAmount { amount currencyCode } } }
    userErrors { field message }
  }
}

GET_CART.query:
query GetCart($cartId: ID!) {
  cart(id: $cartId) {
    id
    checkoutUrl
    totalQuantity
    cost {
      subtotalAmount { amount currencyCode }
      totalTaxAmount { amount currencyCode }
      totalAmount { amount currencyCode }
    }
    lines(first: 100) {
      edges {
        node {
          id
          quantity
          cost { totalAmount { amount currencyCode } }
          merchandise {
            ... on ProductVariant {
              id
              title
              price { amount currencyCode }
              compareAtPrice { amount currencyCode }
              image { url altText }
              product {
                id
                title
                handle
                featuredImage { url altText }
              }
            }
          }
        }
      }
    }
  }
}
